 this.remove(object.id);item={object,component,componentId:component.id,p,signature,body,colliders,attachments:new Map(),pins:new Map([...pinsFor(p)].map(i=>[i,localPoint(p,i,new Vector3())])),generation:++this.generation,version:0,matrix:matrix.clone(),dirty:true,collisionEnabled:object.collisionEnabled!==false};this.syncDistance(item);this.items.set(object.id,item);for(let i=0;i<body.numMeshes();i++){const collider=body.meshCollider(i);if(collider)this.space.colliders.set(collider.handle,{object,component,p:{layer:p.layer,mask:p.mask,collisionMode:'both',trigger:false},collider,is2D:this.is2D,softBody:true,signature});}this.publishItem(item);
