 edgePage(object,{offset=0,limit=64}={}){const item=this.require(object),body=item.body,total=body.numEdges();if(!Number.isSafeInteger(offset)||offset<0||!Number.isSafeInteger(limit)||limit<1||limit>256)throw Error('변형체 연결 페이지 범위를 확인하세요.');if(!item.edgeIndices||item.edgeIndices.length!==total*2)item.edgeIndices=body.edges();const items=[],a={x:0,y:0,z:0},b={x:0,y:0,z:0};for(let index=offset;index<Math.min(total,offset+limit);index++){const from=item.edgeIndices[index*2],to=item.edgeIndices[index*2+1];body.particlePosition(from,a);body.particlePosition(to,b);const restLength=body.edgeRestLength(index),length=Math.hypot(b.x-a.x,b.y-a.y,this.is2D?0:b.z-a.z);items.push({index,particles:[from,to],restLength,length,elasticStrain:restLength>0?length/restLength-1:0,plasticStrain:body.edgePlasticStrain(index),bending:body.isEdgeBend(index),impulse:body.edgeImpulse(index)});}return{view:'edges',generation:item.generation,version:item.version,offset,total,items,nextOffset:offset+limit<total?offset+limit:null};}
